package dev.redstoneengineering.block;import com.mojang.serialization.MapCodec;import dev.redstoneengineering.*;import dev.redstoneengineering.physics.InformationRuntime;import net.minecraft.core.*;import net.minecraft.network.chat.Component;import net.minecraft.world.*;import net.minecraft.server.level.ServerLevel;import net.minecraft.util.RandomSource;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.*;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.phys.BlockHitResult;public class HydroacousticReceiverBlock extends PassiveDirectionalSignalBlock{public HydroacousticReceiverBlock(Properties p){super(p);}@Override public MapCodec<HydroacousticReceiverBlock> codec(){return RedstoneEngineering.HYDROACOUSTIC_RECEIVER_CODEC.value();}@Override protected int computeOutput(Level l,BlockPos p,BlockState s){return Math.min(15,InformationRuntime.value(l,"hydro",p));}@Override protected void onPlace(BlockState s,Level l,BlockPos p,BlockState o,boolean m){super.onPlace(s,l,p,o,m);if(l instanceof ServerLevel sl)sl.scheduleTick(p,this,4);}@Override protected void tick(BlockState s,ServerLevel l,BlockPos p,RandomSource r){int v=InformationRuntime.value(l,"hydro",p);if(v>0)InformationRuntime.write(l,"hydro",p,Math.max(0,v-1),InformationRuntime.aux(l,"hydro",p),v>1,Math.max(0,InformationRuntime.quality(l,"hydro",p)-5));updateOutput(l,p,s,outputValue(l,p,s));l.scheduleTick(p,this,4);}@Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player pl,BlockHitResult h){if(!l.isClientSide)pl.displayClientMessage(Component.literal("Hydroacoustic A="+InformationRuntime.value(l,"hydro",p)+" f="+InformationRuntime.aux(l,"hydro",p)),true);return InteractionResult.sidedSuccess(l.isClientSide);}}